CREATE TABLE users (id serial PRIMARY KEY,name varchar(160) NOT NULL,email varchar(320) NOT NULL UNIQUE,password_hash text NOT NULL,role varchar(64) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE clients (id serial PRIMARY KEY,external_id varchar(160),name varchar(240) NOT NULL,contact_person varchar(240),email varchar(320),phone varchar(64),status varchar(32) NOT NULL DEFAULT 'ACTIVE',account_owner_id integer REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE services (id serial PRIMARY KEY,name varchar(240) NOT NULL UNIQUE,description text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_schedules (id serial PRIMARY KEY,client_id integer NOT NULL REFERENCES clients(id),service_id integer REFERENCES services(id),billing_type varchar(64) NOT NULL,billing_from date,billing_to date,expected_amount numeric(14,2) NOT NULL,due_date date NOT NULL,recurrence varchar(64),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments (id serial PRIMARY KEY,client_id integer REFERENCES clients(id),payment_schedule_id integer REFERENCES payment_schedules(id),client varchar(240) NOT NULL,service varchar(240) NOT NULL,owner varchar(240) NOT NULL,billing_from date,billing_to date,expected_amount numeric(14,2) NOT NULL,due_date date NOT NULL,status varchar(32) NOT NULL,source_reference varchar(240),paid_amount numeric(14,2),paid_date date,transaction_id varchar(240),utr varchar(240),detected_amount numeric(14,2),verified_at timestamptz,verified_by integer REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX payment_dedupe ON payments(client,service,billing_from,billing_to,due_date);
CREATE UNIQUE INDEX payment_source_reference ON payments(source_reference);
CREATE TABLE payment_proofs (id serial PRIMARY KEY,payment_id integer NOT NULL REFERENCES payments(id),file_key text NOT NULL,file_name varchar(512) NOT NULL,file_type varchar(128) NOT NULL,file_size integer NOT NULL,uploaded_by integer REFERENCES users(id),uploaded_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_verifications (id serial PRIMARY KEY,payment_id integer NOT NULL REFERENCES payments(id),proof_id integer REFERENCES payment_proofs(id),extracted_amount numeric(14,2),extracted_date date,transaction_id varchar(240),utr varchar(240),extracted_status varchar(64),confidence numeric(5,4),result varchar(64),reason text,reviewed_by integer REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_reminders (id serial PRIMARY KEY,payment_id integer NOT NULL REFERENCES payments(id),type varchar(64) NOT NULL,scheduled_for timestamptz NOT NULL,sent_at timestamptz,channel varchar(64) NOT NULL,status varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX reminder_once ON payment_reminders(payment_id,type);
CREATE TABLE notifications (id serial PRIMARY KEY,user_id integer REFERENCES users(id),payment_id integer REFERENCES payments(id),type varchar(64) NOT NULL,title varchar(240) NOT NULL,message text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id serial PRIMARY KEY,payment_id integer REFERENCES payments(id),user_id integer REFERENCES users(id),entity_type varchar(64) NOT NULL DEFAULT 'payment',entity_id varchar(240),action varchar(96) NOT NULL,old_value text,new_value text,metadata jsonb,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sync_logs (id serial PRIMARY KEY,started_at timestamptz NOT NULL,completed_at timestamptz,records_processed integer NOT NULL DEFAULT 0,records_created integer NOT NULL DEFAULT 0,records_updated integer NOT NULL DEFAULT 0,records_skipped integer NOT NULL DEFAULT 0,records_failed integer NOT NULL DEFAULT 0,status varchar(64) NOT NULL,error_details jsonb);
